      "duration": 0.1
    },
    {
      "keystrokes": "cat > /etc/nginx/conf.d/benchmark_rate_limit_zone.conf << EOF\n\\(    limit_req_zone \\$binary_remote_addr zone=benchmark_ips:10m rate=10r/s;\n\\)\nEOF\n",
      "duration": 0.1
    },
    {
      "keystrokes": "sed -i '/http {/,http} {/c\\(    log_format benchmark_log '\\$remote_addr - - \\$http_user_agent \\$time_local \\$request_method \\$uri \\$status;'\\)\n' /etc/nginx/nginx.conf\n",
      "duration": 0.1
    },
    {
      "keystrokes": "cat > /etc/nginx/conf.d/benchmark-site.conf << EOF\nserver {\n    listen 8080;\n    server_name localhost;\n\n    root /var/www/html;\n    index index.html;\n\n    # Logging and Error Handling\n    access_log /var/log/nginx/benchmark-access.log benchmark_log;\n    error_log /var/log/nginx/benchmark-error.log warn;\n\n    # Rate Limiting and Custom 404 Page\n    limit_req zone=benchmark_ips burst=10;\n    error_page 404 /404.html;\n\n    location / {\n        try_files \$uri \$uri/ =404;\n    }\n}\nEOF\n",
      "duration": 0.1
    },
    {
      "keystrokes": "rm /etc/nginx/sites-enabled/default\n",
      "duration": 0.1
    },
    {
      "keystrokes": "nginx -t\n",
      "duration": 1.0
    },
    {
      "keystrokes": "systemctl restart nginx\n",
      "duration": 1.0
    },
    {
      "keystrokes": "echo \"Access logs are located at /var/log/nginx/benchmark-access.log\"\n",
      "duration": 0.1
    }
  ],
  "task_complete": true
}
